function validate([side, points, k]) {
  if (side < 1 || side > 1000000000) return 'side is between 1 and 1,000,000,000.';
  if (points.length < 4 || points.length > Math.min(4 * side, 15000)) return 'points needs 4 to min(4 * side, 15,000) entries.';
  const seen = new Set();
  for (const point of points) {
    if (point.length !== 2) return 'Each point is a pair [x, y].';
    const [x, y] = point;
    if (x < 0 || x > side || y < 0 || y > side) return 'Each point lies inside the square from (0, 0) to (side, side).';
    if (x !== 0 && x !== side && y !== 0 && y !== side) return 'Each point lies on the boundary of the square.';
    const key = x + ',' + y;
    if (seen.has(key)) return 'The points are distinct.';
    seen.add(key);
  }
  if (k < 4 || k > Math.min(25, points.length)) return 'k is between 4 and min(25, points.length).';
  return null;
}

