function maxDistance(side, points, k) {
  const perimeter = 4 * side;
  const positions = points.map(([x, y]) => {
    if (x === 0) return y;
    if (y === side) return side + x;
    if (x === side) return 3 * side - y;
    return perimeter - x;
  });
  positions.sort((a, b) => a - b);
  const n = positions.length;

  function canPlace(distance) {
    const next = new Array(n);
    let j = 0;
    for (let i = 0; i < n; i++) {
      while (j < n && positions[j] - positions[i] < distance) {
        j++;
      }
      next[i] = j;
    }
    for (let start = 0; start < n; start++) {
      let last = start;
      let count = 1;
      while (count < k && next[last] < n) {
        last = next[last];
        count++;
      }
      if (count < k) {
        return false;
      }
      if (positions[start] + perimeter - positions[last] >= distance) {
        return true;
      }
    }
    return false;
  }

  let low = 1;
  let high = side;
  while (low < high) {
    const mid = Math.ceil((low + high) / 2);
    if (canPlace(mid)) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

