function maxDistance(side, points, k) {
  // Try every group of k points and keep the best smallest pairwise Manhattan distance.
  let best = 0;
  const group = [];
  const choose = (from) => {
    if (group.length === k) {
      let closest = Infinity;
      for (let a = 0; a < k; a++)
        for (let b = a + 1; b < k; b++)
          closest = Math.min(closest, Math.abs(group[a][0] - group[b][0]) + Math.abs(group[a][1] - group[b][1]));
      best = Math.max(best, closest);
      return;
    }
    for (let i = from; i <= points.length - (k - group.length); i++) {
      group.push(points[i]);
      choose(i + 1);
      group.pop();
    }
  };
  choose(0);
  return best;
}

