function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // A clockwise walk of p units from (0, 0) along the boundary ends at this point.
  const toPoint = (side, p) => p <= side ? [0, p] : p <= 2 * side ? [p - side, side] : p <= 3 * side ? [side, 3 * side - p] : [4 * side - p, 0];
  const side = size === 'small'
    ? (rand() < 0.35 ? int(1, 1000000000) : int(1, 4))
    : (rand() < 0.5 ? int(500, 3000) : int(100000000, 1000000000));
  const perimeter = 4 * side;
  const n = size === 'small' ? int(4, Math.min(perimeter, 11)) : int(1500, 2000);
  const k = int(4, Math.min(25, n));
  const taken = new Set();
  if (perimeter <= 20000) {
    // Few lattice points: shuffle them all and keep the first n.
    const all = Array.from({ length: perimeter }, (_, p) => p);
    for (let i = 0; i < n; i++) {
      const j = int(i, perimeter - 1);
      [all[i], all[j]] = [all[j], all[i]];
      taken.add(all[i]);
    }
  } else {
    // Many lattice points: spread them out, or crowd them around the corners or one random spot.
    const shape = size === 'small' ? int(0, 2) : 0;
    const spot = int(0, perimeter - 1);
    while (taken.size < n) {
      const p = shape === 0 ? int(0, perimeter - 1)
        : shape === 1 ? int(0, 3) * side + int(-3, 3)
        : spot + int(-6, 6);
      taken.add(((p % perimeter) + perimeter) % perimeter);
    }
  }
  const points = [...taken].map(p => toPoint(side, p));
  for (let i = points.length - 1; i > 0; i--) {
    const j = int(0, i);
    [points[i], points[j]] = [points[j], points[i]];
  }
  return [side, points, k];
}
